        if cvss_score is None:
            audit_cvss = entry.get('cvss', {}).get('score')
            if audit_cvss and audit_cvss > 0:
                cvss_score = float(audit_cvss)
        # Fallback to NVD if still missing and we have CVE
        if cvss_score is None and cve != 'N/A':
            # use the first CVE id for lookup
            first_cve = cve.split('|')[0]
            cvss_score = fetch_nvd_score(first_cve)

        cvss_str = f'{cvss_score:.1f}' if isinstance(cvss_score, (int, float)) else 'N/A'
        fixed = '|'.join(sorted(set(fixed_versions))) if fixed_versions else None

        # fallback fixed version from npm audit if OSV has none
        if not fixed:
            fix_avail = vuln.get('fixAvailable')
            if isinstance(fix_avail, dict) and fix_avail.get('version'):
                fixed = fix_avail['version']
        if not fixed:
            fixed = 'N/A'

        final_title = osv_title or title or 'N/A'
        ref_url = url or (osv.get('references', [{}])[0].get('url') if osv else '')
        ref_url = ref_url or 'N/A'

        for ver in versions:
            key = (pkg_name, ver, cve, severity.upper(), cvss_str, fixed, final_title, ref_url)
            if key in seen:
                continue
            seen.add(key)
            rows.append({
                'Package': pkg_name,
                'Version': ver,
                'CVE_ID': cve,
                'Severity': severity.upper(),
                'CVSS_Score': cvss_str,
                'Fixed_Version': fixed,
                'Title': final_title.strip().replace('\n', ' '),
                'Url': ref_url,
            })

# Sort: severity (CRITICAL first), package name
sev_order = {'CRITICAL': 0, 'HIGH': 1}
rows.sort(key=lambda r: (sev_order.get(r['Severity'], 9), r['Package'], r['Version']))

with open(OUT_PATH, 'w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=['Package','Version','CVE_ID','Severity','CVSS_Score','Fixed_Version','Title','Url'])
    writer.writeheader()
    writer.writerows(rows)

print(f'Wrote {len(rows)} rows to {OUT_PATH}')
